import{_ as t}from"./chunks/geoml-archi.BT6sIk6p.js";import{_ as r,o as a,c as o,a0 as n}from"./chunks/framework.Ckbw5VQO.js";const u=JSON.parse('{"title":"GeoML","description":"","frontmatter":{},"headers":[],"relativePath":"about/introduction.md","filePath":"about/introduction.md"}'),i={name:"about/introduction.md"};function l(s,e,c,d,p,f){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="geoml" tabindex="-1">GeoML <a class="header-anchor" href="#geoml" aria-label="Permalink to &quot;GeoML&quot;">​</a></h1><p><strong>GeoML</strong> is a hands-on geospatial machine learning project: train object-detection models on real aerial imagery, export them to <a href="https://onnx.ai/" target="_blank" rel="noreferrer">ONNX</a>, and ship a fully static SPA that runs inference directly in the browser, no backend required.</p><img src="'+t+'" style="display:block;margin:2rem auto;width:100%;"><ul><li><strong>A React SPA</strong> drives the map (<a href="https://maplibre.org/projects/gl-js/" target="_blank" rel="noreferrer">MapLibre</a>) and runs <a href="https://www.oracle.com/artificial-intelligence/ai-inference/" target="_blank" rel="noreferrer">inference</a> locally via <a href="https://onnxruntime.ai/docs/tutorials/web/" target="_blank" rel="noreferrer">ONNX Runtime Web</a>. Tile layers (<a href="https://cartes.gouv.fr/aide/fr/guides-utilisateur/utiliser-les-services-de-la-geoplateforme/diffusion/wmts/" target="_blank" rel="noreferrer">IGN WMTS</a>, <a href="https://wiki.openstreetmap.org/wiki/Main_Page" target="_blank" rel="noreferrer">OSM</a>…) are fetched directly from the browser.</li><li><strong>An offline training pipeline</strong> downloads raw IGN satellite tiles and BD TOPO/OSM polygons, automatically generates an annotated dataset in <a href="https://docs.ultralytics.com/datasets/detect#supported-dataset-formats" target="_blank" rel="noreferrer">YOLO format</a>, fine-tunes a <a href="https://docs.ultralytics.com/models/yolov8#overview" target="_blank" rel="noreferrer">YOLOv8</a> model, and exports <code>.onnx</code> weights bundled with the SPA.</li></ul><div class="tip custom-block"><p class="custom-block-title">Why no backend</p><p><a href="https://docs.ultralytics.com/models/yolov8#overview" target="_blank" rel="noreferrer">YOLOv8n</a> models are small enough (~12 MB each) to run client-side via <a href="https://webassembly.org/" target="_blank" rel="noreferrer">WebAssembly</a>.</p></div>',5)])])}const g=r(i,[["render",l]]);export{u as __pageData,g as default};
